def priority(item, bins):
    return np.log(bins / item + 1)

import numpy as np

def priority(item, bins):
    return np.log(bins - item + 1)

import numpy as np

# MECHANISM: Adjust the priority function to give higher scores to larger remaining capacities
# and use a logarithmic scale to reduce the impact of very small gaps.

def priority(item, bins):
    return np.log(bins - item + 1e-10) / np.log(150)

import numpy as np

