import numpy as np

def priority(item, bins):
    remaining_capacity = bins - item
    return remaining_capacity / (item + 1e-6)

# MECHANISM: Use a combination of remaining capacity and item size to prioritize bins

import numpy as np

def priority(item, bins):
    remaining_capacity = bins - item
    return remaining_capacity / (item + 1e-6) - np.log(remaining_capacity + 1e-6)

# MECHANISM: Use a weighted combination of remaining capacity and item size to prioritize bins

import numpy as np

def priority(item, bins):
    remaining_capacity = bins - item
    return remaining_capacity * (item / (item + 1e-6)) - np.log(remaining_capacity + 1e-6)
